import { useState } from "react";
import "../App.css";

function ProfileAnalyzer() {
  const [profileText, setProfileText] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const analyzeProfile = async () => {
    if (!profileText.trim()) {
      setError("Please enter your profile.");
      return;
    }

    setLoading(true);
    setError("");
    setResult(null);

    try {
      const token = localStorage.getItem("gigora_access_token");

const response = await fetch(
  "http://127.0.0.1:8000/api/profile/",
  {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      profile_text: profileText,
    }),
  }
);

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.detail || "Something went wrong."
        );
      }

      setResult(data);
      window.dispatchEvent(new Event("dashboard-update"));
    } catch (err) {
      setError(err.message);
    }

    setLoading(false);
  };

return (
  <div className="min-h-screen bg-slate-50 px-6 py-10">
    <div className="mx-auto max-w-5xl">

      {/* Header */}

      <div className="mb-8">
        <h1 className="text-4xl font-bold text-[#1E3A5F]">
          AI Profile Analyzer
        </h1>

        <p className="mt-3 text-lg text-[#6B7280]">
          Analyze your Fiverr or Upwork profile and receive AI-powered
          recommendations to improve your profile and win more clients.
        </p>
      </div>

      {/* Card */}

      <div className="rounded-3xl bg-white p-8 shadow-lg">

        {/* Textarea */}

        <div>
          <label className="mb-3 block text-sm font-semibold text-[#1E3A5F]">
            Profile Description
          </label>

          <textarea
            placeholder="Paste your Fiverr or Upwork profile here..."
            value={profileText}
            onChange={(e) => setProfileText(e.target.value)}
            className="min-h-[220px] w-full rounded-2xl border border-gray-300 px-5 py-4 text-[#111827] outline-none transition focus:border-[#1A56DB] focus:ring-4 focus:ring-blue-100"
          />
        </div>

        {/* Button */}

        <div className="mt-8 flex gap-4">

          <button
            onClick={analyzeProfile}
            disabled={loading}
            className="rounded-xl bg-[#1A56DB] px-8 py-4 font-semibold text-white transition hover:bg-[#1E3A5F] disabled:cursor-not-allowed disabled:opacity-60"
          >
            {loading ? "Analyzing..." : "Analyze Profile"}
          </button>

        </div>

        {/* Error */}

        {error && (

          <div className="mt-6 rounded-xl border border-red-200 bg-red-50 p-4 text-red-600">
            {error}
          </div>

        )}

        {/* Results */}

        {result && (

          <div className="mt-10 space-y-8">

            {/* Score */}

            <div className="rounded-3xl bg-gradient-to-r from-[#1A56DB] to-[#1E3A5F] p-8 text-center text-white">

              <p className="text-lg font-medium">
                Overall Profile Score
              </p>

              <h2 className="mt-3 text-6xl font-bold">
                {result.score}/10
              </h2>

            </div>

            {/* Cards */}

            <div className="grid gap-6 lg:grid-cols-3">

              {/* Strengths */}

              <div className="rounded-2xl bg-white p-6 shadow">

                <h3 className="mb-5 text-xl font-bold text-[#059669]">
                  Strengths
                </h3>

                <ul className="space-y-3">

                  {result.strengths?.map((item, index) => (

                    <li
                      key={index}
                      className="flex items-start gap-2 text-[#111827]"
                    >
                      <span className="mt-1 text-[#059669]">
                        ✓
                      </span>

                      <span>{item}</span>

                    </li>

                  ))}

                </ul>

              </div>

              {/* Weaknesses */}

              <div className="rounded-2xl bg-white p-6 shadow">

                <h3 className="mb-5 text-xl font-bold text-red-600">
                  Weaknesses
                </h3>

                <ul className="space-y-3">

                  {result.weaknesses?.map((item, index) => (

                    <li
                      key={index}
                      className="flex items-start gap-2 text-[#111827]"
                    >
                      <span className="mt-1 text-red-500">
                        ✕
                      </span>

                      <span>{item}</span>

                    </li>

                  ))}

                </ul>

              </div>

              {/* Suggestions */}

              <div className="rounded-2xl bg-white p-6 shadow">

                <h3 className="mb-5 text-xl font-bold text-[#1A56DB]">
                  Suggestions
                </h3>

                <ul className="space-y-3">

                  {result.suggestions?.map((item, index) => (

                    <li
                      key={index}
                      className="flex items-start gap-2 text-[#111827]"
                    >
                      <span className="mt-1 text-[#1A56DB]">
                        →
                      </span>

                      <span>{item}</span>

                    </li>

                  ))}

                </ul>

              </div>

            </div>

          </div>

        )}

      </div>

    </div>
  </div>
);
}

export default ProfileAnalyzer;
